        $packed = \inet_pton($ip);
        if ($packed === false || \strlen($packed) !== 16) {
            return false;
        }

        switch ($packed[0]) {
            case "\x24":
                return (\str_starts_with($packed, "\x24\x00\xcb\x00")) // 2400:cb00::/32
                    || (\str_starts_with($packed, "\x24\x05\xb5\x00")) // 2405:b500::/32
